INSERT INTO races (race_id,name,category,tier,notes) VALUES (1,'Slime','Monster','Base','The weakest common monster; the form Rimuru is reborn into.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (2,'Demon Slime','Monster','Evolved','The apex of slime evolution, reached by awakening as a True Demon Lord.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (3,'Goblin','Humanoid','Base','Small forest humanoids, weak on their own.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (4,'Hobgoblin','Humanoid','Evolved','The evolved form of goblins after being named by a powerful monster.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (5,'Ogre','Humanoid','Base','Strong horned humanoids; the surviving ogre village that joined Rimuru.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (6,'Kijin','Humanoid','Evolved','Ogres evolved into a refined oni-like race after Rimuru named them.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (7,'Oni','Humanoid','Evolved','The higher oni forms the kijin reach at the Harvest Festival.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (8,'Direwolf','Monster','Base','Pack-hunting wolves of the Great Jura Forest.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (9,'Tempest Wolf','Monster','Evolved','Direwolves evolved under Veldora''s influence and Rimuru''s naming.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (10,'Tempest Star Wolf','Monster','Evolved','The leader variant of the star wolf line; Ranga''s form.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (11,'Lizardman','Monster','Base','Marsh-dwelling reptilian humanoids.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (12,'Dragonewt','Dragon','Evolved','Lizardmen who reawaken their dragon roots, often through naming.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (13,'Orc','Monster','Base','Pig-like humanoids that swarm in famine.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (14,'High Orc','Monster','Evolved','The evolved orc form that serves Tempest under Geld.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (15,'Orc Disaster','Monster','Evolved','A Demon Lord seed; the evolution of an Orc Lord that devours its own kind.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (16,'Dwarf','Humanoid','Base','Master craftsmen of the Armed Nation of Dwargon.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (17,'Human','Human','Base','The dominant people of the western nations.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (18,'Otherworlder','Human','Base','People summoned or reincarnated from another world, often carrying unique skills.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (19,'Elf','Humanoid','Base','Long-lived people of the Sorcerous Dynasty of Sarion.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (20,'High Elf','Humanoid','Evolved','The elder elven line; the Empress Elmesia''s kind.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (21,'Dryad','Spirit','Base','Tree spirits that guard the Great Jura Forest.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (22,'Pixie','Spirit','Base','Tiny fairy spirits; Ramiris''s race.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (23,'Demon','Demon','Base','Beings from the spirit world, ranging from lesser to arch demons.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (24,'Primordial Demon','Demon','Evolved','The seven oldest demons, each known by a colour rather than a name.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (25,'Majin','Demon','Base','Demon-kin; the clown troupe and several schemers belong here.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (26,'Dragonoid','Dragon','Base','The rare children of a True Dragon; Milim''s race.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (27,'True Dragon','Dragon','Base','The four near-immortal apex dragons of the world.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (28,'Vampire','Undead','Base','Blood-drinking nobles; the Valentine line of Lubelius.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (29,'Wight','Undead','Evolved','Powerful undead sorcerers; the Wight King guards the labyrinth.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (30,'Insectar','Monster','Evolved','Insect-kin of the labyrinth, led by the Insect Kaiser.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (31,'Beastfolk','Beastfolk','Base','Animal-featured warriors of the Beast Kingdom of Eurazania.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (32,'Winged','Winged','Base','Sky-dwelling harpy people; Frey''s race.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (33,'Giant','Giant','Base','Titanic beings; Dagruel''s kind.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (34,'Seraph','Spirit','Base','Angelic beings tied to the world''s guardian system; Dino''s true nature.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (35,'Mystic Fox','Monster','Evolved','Nine-tailed mystic foxes; Kumara is a young Ninehead of this line.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (36,'Wicked Oni','Humanoid','Evolved','The higher oni form Shion reached when she was revived through daemons.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (37,'Arch Doll','Construct','Evolved','A daemon bound into a crafted golem body, as with Beretta.');
INSERT INTO races (race_id,name,category,tier,notes) VALUES (38,'Metal Daemon','Demon','Evolved','A daemon of living metal; the form Gadra took after his reincarnation.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (1,1,'Reincarnation in the Jura Forest','Vol 1','Season 1 Part 1','A man reborn as a slime befriends the sealed dragon Veldora, then names the goblins and direwolves and forms the first forest alliance.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (2,2,'The Dwarven Kingdom','Vol 1','Season 1 Part 1','Rimuru visits the Armed Nation of Dwargon, gains the smith Kaijin, and draws the eye of King Gazel.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (3,3,'War of the Orc Disaster','Vol 2','Season 1 Part 1','The Orc Lord ravages the forest, the ogre survivors are named into kijin, and the Great Jura Forest alliance is forged.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (4,4,'Founding of the Nation','Vol 3','Season 1 Part 2','The Jura Tempest Federation is founded, holds its opening festival, and the demon lords begin to take notice.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (5,5,'The Teacher and the Otherworlders','Vol 4','Season 1 Part 2','Rimuru teaches the summoned children in Ingracia, learns Shizu''s past, and first crosses the holy knight Hinata.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (6,6,'Clayman''s Web','Vol 4-5','Season 2 Part 1','Milim, the monster Charybdis, and the schemer Clayman pull the demon lords toward open conflict.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (7,7,'The Falmuth Invasion','Vol 5','Season 2 Part 1','Falmuth and Hinata strike Tempest while Rimuru is away, and many of its people are killed.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (8,8,'The Harvest Festival','Vol 5','Season 2 Part 1','Rimuru awakens as a True Demon Lord, revives the fallen, and the whole of Tempest evolves.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (9,9,'Walpurgis, the Demon Lords'' Banquet','Vol 5-6','Season 2 Part 2','Clayman is defeated at the demon lords'' banquet and the eight-seat Octagram is formed.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (10,10,'Hinata and the Holy Church','Vol 7','Season 3','The clash and reconciliation with the Holy Empire of Lubelius, and the truth of the vampire demon lord Luminous.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (11,11,'The Founding Festival and the Labyrinth','Vol 9','Season 3','Tempest opens to the world with a festival and tournament, and Ramiris''s labyrinth is raised under the city.');
INSERT INTO arcs (arc_id,sequence_no,name,ln_volumes,anime_coverage,summary) VALUES (12,12,'War with the Eastern Empire','Vol 13-14','Season 3','The vast Eastern Empire invades the forest and is broken by Tempest''s officers and the freed Veldora.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (1,'Raphael, Lord of Wisdom','Ultimate Skill','Analysis','Evolved from Great Sage; runs Rimuru''s analysis, calculation, and skill control.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (2,'Beelzebuth, Lord of Gluttony','Ultimate Skill','Predation','Evolved from Gluttony; devours and stores targets and their abilities.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (3,'Uriel, Lord of Vows','Ultimate Skill','Support','Barrier and spatial control bound to promises Rimuru makes.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (4,'Azathoth, Void God','Ultimate Skill','Spatial','Rimuru''s later fused ultimate governing void and space.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (5,'Amaterasu, Lord of the Blazing Sun','Ultimate Skill','Elemental','Benimaru''s flame ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (6,'Tsukuyomi, Lord of Moon Shadow','Ultimate Skill','Spatial','Souei''s shadow and space ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (7,'Susanoo, Lord of Tyranny','Ultimate Skill','Combat','Shion''s ultimate, evolved from her unique skill Cook.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (8,'Azazel, Lord of Temptation','Ultimate Skill','Manipulation','Diablo''s ultimate, formed from Tempter and Seeker.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (9,'Mammon, Lord of Greed','Ultimate Skill','Manipulation','Yuuki''s sin-series ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (10,'Metatron, Lord of Purity','Ultimate Skill','Elemental','Leon Cromwell''s light ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (11,'Faust, Lord of Investigation','Ultimate Skill','Analysis','Veldora''s analysis ultimate, learned partly from Rimuru.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (12,'Veldora, Lord of Storms','Ultimate Skill','Elemental','Rimuru''s ultimate, gained by absorbing the remains of Veldora inside Beelzebuth.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (13,'Michael, Lord of Justice','Ultimate Skill','Manipulation','The controlling angel ultimate held by Emperor Rudra.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (14,'Lucifer, Lord of Pride','Ultimate Skill','Manipulation','Guy Crimson''s sin-series ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (15,'Satanael, Lord of Wrath','Ultimate Skill','Elemental','Milim''s sin-series ultimate, powering her magicule breeder reactor.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (16,'Mephisto, Lord of Fantasy','Ultimate Skill','Manipulation','Zegion''s illusion and space ultimate.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (17,'Fortuna','Ultimate Skill','Analysis','Hinata''s precognition ultimate, an evolution of Mathematician.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (18,'Predator','Unique Skill','Predation','Rimuru''s starting skill; consumes and copies targets.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (19,'Great Sage','Unique Skill','Analysis','Rimuru''s starting analysis skill; evolves into Raphael.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (20,'Gluttony','Unique Skill','Predation','The higher predation skill that evolves into Beelzebuth.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (21,'Generalissimo','Unique Skill','Support','Benimaru''s command skill for directing troops.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (22,'Analyst','Unique Skill','Analysis','Shuna''s skill for reading and understanding anything she studies.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (23,'Manufacturer','Unique Skill','Support','Shuna''s crafting and production skill.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (24,'Cook','Unique Skill','Support','Shion''s skill that makes any imagined result come out right.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (25,'Tempter','Unique Skill','Manipulation','Diablo''s temptation skill; folds into Azazel.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (26,'Seeker','Unique Skill','Analysis','Diablo''s investigation skill; folds into Azazel.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (27,'Mathematician','Unique Skill','Analysis','Hinata''s calculation skill that predicts an opponent''s moves.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (28,'Creator','Unique Skill','Manipulation','Yuuki''s unique skill that fabricates other skills and abilities.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (29,'Manipulator','Unique Skill','Manipulation','Clayman''s unique skill for controlling people and running a spy network.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (30,'Chosen One','Unique Skill','Support','Masayuki''s luck skill that bends situations in his favour.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (31,'Infinite Regeneration','Intrinsic Skill','Support','Rimuru''s slime-body regeneration.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (32,'Universal Shapeshift','Intrinsic Skill','Manipulation','Rimuru''s ability to mimic any form he has predated.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (33,'Universal Perception','Intrinsic Skill','Analysis','Full-space sensing shared by several apex beings.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (34,'Black Lightning','Extra Skill','Elemental','Ranga''s signature storm attack.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (35,'Shadow Motion','Intrinsic Skill','Spatial','Souei''s movement through shadows.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (36,'Drago Nova','Extra Skill','Elemental','Milim''s devastating dragon energy blast.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (37,'Vortex Spear','Extra Skill','Elemental','Gabiru''s spinning water attack.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (38,'Flame Manipulation','Extra Skill','Elemental','The flame power Shizu wielded while hosting the spirit Ifrit.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (39,'Martial Master','Unique Skill','Combat','Hakurou''s peerless swordsmanship.');
INSERT INTO skills (skill_id,name,skill_type,category,notes) VALUES (40,'Shadow Striker','Unique Skill','Spatial','Souei''s covert-operations unique skill.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (1,'Jura Tempest Federation Leadership','Government','Tempest','The ministers and officers who run Rimuru''s nation.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (2,'Twelve Guardian Lords','Military','Tempest','Tempest''s circle of strongest guardians; the roster grew over time.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (3,'Octagram','Council','Independent','The eight-seat demon lord council formed after Walpurgis.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (4,'Ten Great Demon Lords','Council','Independent','The older ten-seat demon lord order that preceded the Octagram.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (5,'Primordial Demons','Demon group','Independent','The seven oldest demons, each named for a colour.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (6,'Three Devil Girls','Military','Tempest','Testarossa, Ultima, and Carrera, who serve Rimuru as diplomats and executives.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (7,'Holy Knights of Lubelius','Order','Neutral','The crusaders of the Luminism faith, led by Hinata.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (8,'Free Guild','Guild','Neutral','The independent adventurers'' guild spanning the western nations.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (9,'Moderate Harlequin Alliance','Demon group','Antagonist','The clown troupe of schemers behind much of the early conflict.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (10,'Imperial Guardians','Military','Antagonist','The elite officers of the Eastern Empire.');
INSERT INTO factions (faction_id,name,kind,aligned_with,notes) VALUES (11,'Three Beastketeers','Military','Ally','The three strongest beast warriors of Eurazania.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (1,'Jura Tempest Federation','Tempest','Demon Lord state','Rimuru',1,'Self','The monster nation Rimuru builds in the Great Jura Forest.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (2,'Armed Nation of Dwargon','Dwargon','Monarchy','Central',47,'Ally','The dwarven kingdom of craftsmen ruled by the Hero King Gazel.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (3,'Kingdom of Blumund','Blumund','Monarchy','Londo',NULL,'Ally','A small human kingdom bordering the forest; Rimuru''s first foreign contact.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (4,'Kingdom of Falmuth','Falmuth','Monarchy','Falmuth',54,'Former Enemy','A human kingdom that invaded Tempest and lost; later re-founded as the Kingdom of Farmenas under King Youm.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (5,'Sorcerous Dynasty of Sarion','Sarion','Magocracy','Elmine Sarion',48,'Ally','A union of elven states around the Divine Tree, ruled by Empress Elmesia.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (6,'Holy Empire of Lubelius','Lubelius','Theocracy','Lubelius',33,'Rival','The theocracy of the Luminism faith, secretly ruled by the vampire demon lord Luminous.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (7,'Beast Kingdom of Eurazania','Eurazania','Demon Lord state','Eurazania',37,'Ally','The beastfolk nation of the former demon lord Carrion.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (8,'Nasca Namrium Ulmeria United Eastern Empire','Eastern Empire','Empire','Nasca',56,'Enemy','The vast eastern empire of the eternal emperor Rudra, guarded by the Scorch Dragon.');
INSERT INTO nations (nation_id,name,short_name,gov_type,capital,ruler_character_id,relation_to_tempest,notes) VALUES (9,'Kingdom of Englassia','Englassia','Monarchy','Ingrassia',NULL,'Neutral','A western human kingdom, also rendered Ingracia, home to the Free Guild headquarters and Yuuki''s school.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (1,'Rimuru Tempest','The Slime Demon Lord',2,1,'None','Founder and Chancellor of Tempest','Tempest','Alive',1,'Special S','Awakened',251000000,'A man reincarnated as a slime who builds a monster nation and becomes one of the strongest beings alive.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (2,'Veldora Tempest','Storm Dragon',27,1,'Male','Guardian and sworn friend of Rimuru','Tempest','Alive',1,'Special S','None',88126579,'One of the four True Dragons, sealed for centuries until Rimuru freed him.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (3,'Benimaru','Flame Lord',6,1,'Male','Supreme Commander of Tempest''s forces','Tempest','Alive',3,'Special S','None',40000000,'Leader of the ogre survivors, evolved into a kijin and later a flame oni.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (4,'Shuna','Princess of the Oni',6,1,'Female','Head of the Production Department','Tempest','Alive',3,'A+','None',NULL,'Benimaru''s sister, a gentle priestess and skilled craftsperson.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (5,'Shion','Battle Secretary',36,1,'Female','Chief Secretary and bodyguard','Tempest','Revived',3,'Special A','None',4229140,'Rimuru''s fierce secretary, killed in the Falmuth attack and revived at the Harvest Festival.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (6,'Souei',NULL,6,1,'Male','Spymaster','Tempest','Alive',3,'Special A','None',1281162,'A quiet, deadly kijin who runs Tempest''s intelligence network.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (7,'Hakurou','Sword Saint',6,1,'Male','Sword instructor','Tempest','Alive',3,'Special A','None',60000,'The elderly master swordsman of the kijin, teacher to Tempest''s fighters.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (8,'Kurobe',NULL,6,1,'Male','Master blacksmith','Tempest','Alive',3,'A','None',NULL,'The kijin smith who forges Tempest''s finest weapons.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (9,'Rigurd',NULL,4,1,'Male','Prime Minister','Tempest','Alive',1,'A','None',NULL,'The first goblin chief Rimuru named; now the head of Tempest''s civil government.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (10,'Gobta',NULL,4,1,'Male','Captain of the Goblin Riders','Tempest','Alive',1,'A','None',NULL,'A goofy but oddly gifted goblin who leads the wolf-riding cavalry.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (11,'Ranga','Storm Fang',10,1,'Male','Rimuru''s guardian beast','Tempest','Alive',1,'Special A','None',4340084,'The direwolf pup who grew into Rimuru''s loyal storm wolf, living in his shadow.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (12,'Gabiru',NULL,12,1,'Male','Head of the flying corps and research','Tempest','Alive',3,'A','None',NULL,'A proud lizardman leader who becomes a dragonewt and a devoted Tempest officer.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (13,'Souka',NULL,12,1,'Female','Souei''s lieutenant','Tempest','Alive',3,'A','None',NULL,'Gabiru''s sister, a disciplined agent serving under Souei.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (14,'Geld',NULL,14,1,'Male','Chief of construction and defence','Tempest','Alive',3,'Special A','None',2378749,'Named after the fallen Orc Disaster, he leads the orcs who build and defend Tempest.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (15,'Diablo','Noir, the Black Primordial',24,1,'Male','Rimuru''s chief steward','Tempest','Alive',7,'Special S','Awakened',6666666,'One of the seven primordial demons, who begs to serve Rimuru after being summoned.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (16,'Testarossa','Blanc, the White Primordial',24,1,'Female','Diplomat and executive','Tempest','Alive',11,'Special S','Awakened',3333124,'The White Primordial, who serves Rimuru as a fearsome diplomat.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (17,'Ultima','Violet, the Purple Primordial',24,1,'Female','Executive','Tempest','Alive',11,'Special S','Awakened',2668816,'The Purple Primordial, cruel in battle and loyal to Rimuru.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (18,'Carrera','Jaune, the Yellow Primordial',24,1,'Female','Executive','Tempest','Alive',11,'Special S','Awakened',7013351,'The Yellow Primordial, who loves a good fight and serves Rimuru.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (19,'Ramiris','The Labyrinth',22,1,'Female','Demon Lord of the Labyrinth','Ally','Alive',6,'Special A','Self-Proclaimed',NULL,'An ancient, tiny fairy demon lord who moves her labyrinth beneath Tempest.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (20,'Beretta',NULL,37,1,'None','Ramiris''s guardian','Tempest','Alive',11,'Special A','None',NULL,'A demon Rimuru bound into a golem body to protect Ramiris.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (21,'Treyni',NULL,21,1,'Female','Dryad of the Great Jura Forest','Ally','Alive',3,'A+','None',NULL,'The elegant tree spirit who watches over the forest and favours Rimuru.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (22,'Adalmann',NULL,29,1,'Male','Labyrinth guardian and bishop','Tempest','Alive',11,'Special A','None',NULL,'A devout undead sorcerer who guards a floor of the labyrinth.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (23,'Zegion','Insect Kaiser',30,1,'Male','Labyrinth guardian','Tempest','Alive',11,'Special S','None',68889143,'A once-lowly insect who trained under Veldora into one of Tempest''s strongest.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (24,'Kumara',NULL,35,1,'Female','Labyrinth guardian','Tempest','Alive',11,'Special A','None',NULL,'A young nine-tailed spirit beast who guards the labyrinth.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (25,'Gadra',NULL,38,1,'Male','Labyrinth researcher','Tempest','Alive',12,'A+','None',NULL,'A former court mage of the Eastern Empire, reincarnated into a metal daemon, who defects to Tempest and studies its labyrinth.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (26,'Kaijin',NULL,16,1,'Male','Master smith and engineer','Tempest','Alive',2,'B','None',NULL,'A dwarven smith exiled from Dwargon who becomes the backbone of Tempest''s industry.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (27,'Shizue Izawa','Conqueror of Flames',18,NULL,'Female','Hero and teacher','Ally','Deceased',5,'A','None',NULL,'A summoned hero who hosted the flame spirit Ifrit; her memory shapes Rimuru''s human form.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (28,'Veldanava','Star King Dragon',27,NULL,'Male','Progenitor of the world','Neutral','Deceased',NULL,'Special S','None',NULL,'The firstborn True Dragon who shaped the world and fathered Milim; long dead by the main story.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (29,'Velzard','Frost Dragon',27,NULL,'Female','White Ice Dragon','Neutral','Alive',9,'Special S','None',80000000,'The second True Dragon, who keeps company with the demon lord Guy in the frozen north.');
INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (30,'Velgrynd','Scorch Dragon',27,8,'Female','Guardian deity of the Empire','Antagonist','Alive',12,'Special S','None',74350087,'The third True Dragon, who serves Emperor Rudra as his marshal and guardian.');
