INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (33,'Luminous Valentine','Twilight',28,6,'Female','Demon Lord and true ruler of Lubelius','Rival','Alive',10,'Special S','Awakened',20000000,'The vampire demon lord who is secretly worshipped as the god of the Luminism faith.');
