INSERT INTO characters (character_id,name,epithet,race_id,nation_id,gender,role_title,alignment,status,debut_arc_id,threat_rank,demon_lord_class,ep_estimate,notes) VALUES (36,'Dagruel','Wicked God',33,NULL,'Male','Giant Demon Lord','Neutral','Alive',9,'Special S','Awakened',120000000,'A colossal, taciturn demon lord who guards his own domain.');
