INSERT INTO demon_lords (character_id,title,roster,is_awakened,domain,notes) VALUES (1,'Demon Lord Rimuru','Octagram',1,'Jura Tempest Federation','Recognised as a True Demon Lord after the Harvest Festival.');
INSERT INTO demon_lords (character_id,title,roster,is_awakened,domain,notes) VALUES (19,'Labyrinth','Octagram',0,'Tempest Labyrinth','One of the oldest demon lords despite her small stature.');
